import enum
from datetime import date, datetime
from sqlalchemy import Date, DateTime, Enum, Float, ForeignKey, Integer, Numeric, String, Text, func
from sqlalchemy.orm import Mapped, mapped_column, relationship
from ..database import Base

class Role(str, enum.Enum): ADMIN="admin"; PROJECT_MANAGER="project_manager"; DEPARTMENT_HEAD="department_head"; VIEWER="viewer"
class Status(str, enum.Enum): PLANNED="planned"; ON_TRACK="on_track"; AT_RISK="at_risk"; DELAYED="delayed"; COMPLETED="completed"
class RiskLevel(str, enum.Enum): LOW="low"; MEDIUM="medium"; HIGH="high"; CRITICAL="critical"
class User(Base):
    __tablename__="users"; id: Mapped[int]=mapped_column(primary_key=True); email: Mapped[str]=mapped_column(String(255),unique=True,index=True); full_name: Mapped[str]=mapped_column(String(120)); password_hash: Mapped[str]=mapped_column(String(255)); role: Mapped[Role]=mapped_column(Enum(Role),default=Role.VIEWER); created_at: Mapped[datetime]=mapped_column(DateTime(timezone=True),server_default=func.now())
class Department(Base):
    __tablename__="departments"; department_id: Mapped[int]=mapped_column(primary_key=True); department_name: Mapped[str]=mapped_column(String(150),unique=True,index=True); department_head: Mapped[str]=mapped_column(String(120)); total_members: Mapped[int]=mapped_column(Integer); members: Mapped[list["TeamMember"]]=relationship(back_populates="department")
class TeamMember(Base):
    __tablename__="team_members"; member_id: Mapped[int]=mapped_column(primary_key=True); name: Mapped[str]=mapped_column(String(120)); designation: Mapped[str]=mapped_column(String(120)); department_id: Mapped[int]=mapped_column(ForeignKey("departments.department_id")); email: Mapped[str]=mapped_column(String(255),unique=True); phone: Mapped[str|None]=mapped_column(String(30)); availability: Mapped[float]=mapped_column(Float,default=1.0); department: Mapped[Department]=relationship(back_populates="members")
class Project(Base):
    __tablename__="projects"; project_id: Mapped[int]=mapped_column(primary_key=True); project_name: Mapped[str]=mapped_column(String(180),unique=True,index=True); description: Mapped[str]=mapped_column(Text); start_date: Mapped[date]=mapped_column(Date); expected_end_date: Mapped[date]=mapped_column(Date); actual_end_date: Mapped[date|None]=mapped_column(Date); status: Mapped[Status]=mapped_column(Enum(Status),default=Status.PLANNED); progress_percentage: Mapped[float]=mapped_column(Float,default=0); priority: Mapped[str]=mapped_column(String(30)); budget_allocated: Mapped[float]=mapped_column(Numeric(14,2)); budget_used: Mapped[float]=mapped_column(Numeric(14,2),default=0); budget_remaining: Mapped[float]=mapped_column(Numeric(14,2)); risk_level: Mapped[RiskLevel]=mapped_column(Enum(RiskLevel),default=RiskLevel.LOW); predicted_completion_date: Mapped[date|None]=mapped_column(Date); created_at: Mapped[datetime]=mapped_column(DateTime(timezone=True),server_default=func.now()); updated_at: Mapped[datetime]=mapped_column(DateTime(timezone=True),server_default=func.now(),onupdate=func.now()); milestones: Mapped[list["Milestone"]]=relationship(back_populates="project",cascade="all, delete-orphan"); tasks: Mapped[list["Task"]]=relationship(back_populates="project",cascade="all, delete-orphan"); budgets: Mapped[list["Budget"]]=relationship(back_populates="project",cascade="all, delete-orphan"); risks: Mapped[list["Risk"]]=relationship(back_populates="project",cascade="all, delete-orphan"); recommendations: Mapped[list["AIRecommendation"]]=relationship(back_populates="project",cascade="all, delete-orphan")
class Milestone(Base):
    __tablename__="milestones"; milestone_id: Mapped[int]=mapped_column(primary_key=True); project_id: Mapped[int]=mapped_column(ForeignKey("projects.project_id")); title: Mapped[str]=mapped_column(String(180)); deadline: Mapped[date]=mapped_column(Date); status: Mapped[Status]=mapped_column(Enum(Status)); completion_percentage: Mapped[float]=mapped_column(Float,default=0); project: Mapped[Project]=relationship(back_populates="milestones")
class Task(Base):
    __tablename__="tasks"; task_id: Mapped[int]=mapped_column(primary_key=True); project_id: Mapped[int]=mapped_column(ForeignKey("projects.project_id")); assigned_department: Mapped[str]=mapped_column(String(150)); assigned_member: Mapped[str|None]=mapped_column(String(120)); title: Mapped[str]=mapped_column(String(180)); description: Mapped[str]=mapped_column(Text); status: Mapped[Status]=mapped_column(Enum(Status)); priority: Mapped[str]=mapped_column(String(30)); planned_start: Mapped[date]=mapped_column(Date); planned_end: Mapped[date]=mapped_column(Date); actual_end: Mapped[date|None]=mapped_column(Date); completion_percentage: Mapped[float]=mapped_column(Float,default=0); project: Mapped[Project]=relationship(back_populates="tasks")
class Budget(Base):
    __tablename__="budgets"; budget_id: Mapped[int]=mapped_column(primary_key=True); project_id: Mapped[int]=mapped_column(ForeignKey("projects.project_id")); allocated: Mapped[float]=mapped_column(Numeric(14,2)); spent: Mapped[float]=mapped_column(Numeric(14,2)); remaining: Mapped[float]=mapped_column(Numeric(14,2)); financial_year: Mapped[str]=mapped_column(String(20)); project: Mapped[Project]=relationship(back_populates="budgets")
class Risk(Base):
    __tablename__="risks"; risk_id: Mapped[int]=mapped_column(primary_key=True); project_id: Mapped[int]=mapped_column(ForeignKey("projects.project_id")); risk_title: Mapped[str]=mapped_column(String(180)); severity: Mapped[RiskLevel]=mapped_column(Enum(RiskLevel)); probability: Mapped[float]=mapped_column(Float); impact: Mapped[float]=mapped_column(Float); mitigation_plan: Mapped[str]=mapped_column(Text); status: Mapped[Status]=mapped_column(Enum(Status)); project: Mapped[Project]=relationship(back_populates="risks")
class AIRecommendation(Base):
    __tablename__="ai_recommendations"; recommendation_id: Mapped[int]=mapped_column(primary_key=True); project_id: Mapped[int]=mapped_column(ForeignKey("projects.project_id")); recommendation: Mapped[str]=mapped_column(Text); reason: Mapped[str]=mapped_column(Text); confidence_score: Mapped[float]=mapped_column(Float); expected_improvement: Mapped[str]=mapped_column(Text); generated_at: Mapped[datetime]=mapped_column(DateTime(timezone=True),server_default=func.now()); project: Mapped[Project]=relationship(back_populates="recommendations")
